// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CopyIcon, CrosshairIcon, MousePointerClickIcon } from 'lucide-react'
import type { ReactNode } from 'react'

import { BrowserChrome, DemoStage, DockHeader, MockPage, type Build } from '@/app/demos/stage'

import { ATTRIBUTES, CAPTIONS, PICKED_CLASSES, PICKED_TAG, STYLES, TARGETS } from './script'

const build: Build = ({ tl, q, qa, pos, step, final, move, click, count, wait, cursorOut }) => {
  const overlay = q('ov')
  const hover = (index: number, at?: string) => {
    const { d, label } = TARGETS[index]
    const box = pos(d, 0, 0)
    move(d, { at, ax: index === 1 ? 0.3 : 0.5 })
    tl.to(
      overlay,
      {
        x: box.x,
        y: box.y,
        width: box.w,
        height: box.h,
        opacity: 1,
        duration: 0.35,
        ease: 'power3.out',
      },
      '<0.2',
    )
    tl.to(q('ov-label'), { text: { value: label, delimiter: '' }, duration: 0.01 }, '<')
  }

  step(0)
  move('pick')
  click('pick')
  tl.to(q('pick'), { opacity: 0.6, duration: 0.2 }, '<')
  tl.fromTo(
    q('picking'),
    { opacity: 0, y: -6 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'back.out(2)' },
  )

  step(1, '+=0.3')
  hover(0)
  wait(0.4)
  hover(1)
  wait(0.4)
  hover(2)

  step(2, '+=0.4')
  click('page-cta')
  tl.to(q('picking'), { opacity: 0, duration: 0.2 }, '<')
  tl.to(q('pick'), { opacity: 1, duration: 0.2 }, '<')
  tl.to(
    overlay,
    {
      borderColor: '#a5b4fc',
      backgroundColor: 'rgba(99,102,241,0.25)',
      duration: 0.15,
      yoyo: true,
      repeat: 1,
    },
    '<',
  )
  tl.to(q('empty'), { opacity: 0, scale: 0.96, duration: 0.25 }, '<0.1')
  tl.fromTo(
    qa('badge'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.3, stagger: 0.07, ease: 'back.out(2.5)' },
    '<0.15',
  )
  tl.fromTo(
    qa('stat'),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.3, stagger: 0.06, ease: 'power3.out' },
    '<0.1',
  )
  const cta = pos('page-cta', 0, 0)
  const page = pos('page', 0, 0)
  const values = [cta.w, cta.h, cta.x - page.x, cta.y - page.y]
  values.forEach((value, index) =>
    count(`stat-${index}`, Math.round(value), { at: index === 0 ? '<' : '<0.05', duration: 0.7 }),
  )

  step(3, '+=0.4')
  tl.fromTo(
    qa('section'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.35, stagger: 0.12, ease: 'power3.out' },
  )
  tl.fromTo(
    qa('row'),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.25, stagger: 0.05, ease: 'power2.out' },
    '<0.1',
  )
  move('copy-styles', { at: '+=0.2' })
  click('copy-styles')
  tl.fromTo(q('copied'), { opacity: 0, y: 4 }, { opacity: 1, y: 0, duration: 0.25 }, '<')
  tl.to(overlay, { opacity: 0, duration: 0.3 }, '+=0.3')
  cursorOut('<')
  final()
  wait(1.4)
}

function Section({ title, d, children }: { title: string; d?: string; children: ReactNode }) {
  return (
    <div
      data-d="section"
      className="rounded-lg border border-line bg-canvas/60 px-2 py-1.5 opacity-0"
    >
      <div className="mb-0.5 flex items-center justify-between">
        <span className="text-[9.5px] font-medium text-ink">{title}</span>
        <span data-d={d} className="flex h-4 items-center gap-1 text-[8.5px] text-muted">
          {d ? (
            <span data-d="copied" className="text-[var(--accent)] opacity-0">
              Copied
            </span>
          ) : null}
          <CopyIcon className="size-2.5" />
        </span>
      </div>
      <div className="space-y-px font-mono text-[8.5px] leading-[13px]">{children}</div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Element Inspector picking a button on a page and reading its size, attributes and computed styles"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://northwind.app"
        panelWidth={222}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="relative flex min-h-0 flex-1 flex-col gap-1 p-2">
              <span
                data-d="pick"
                className="flex h-7 w-fit items-center gap-1.5 rounded-lg bg-[var(--accent)] px-2.5 text-[10px] font-medium text-canvas"
              >
                <CrosshairIcon className="size-3" /> Pick element on page
              </span>
              <div
                data-d="empty"
                className="absolute inset-x-2.5 top-12 flex flex-col items-center gap-1.5 rounded-lg border border-dashed border-line-strong py-8 text-center text-[9.5px] text-muted"
              >
                <MousePointerClickIcon className="size-5" />
                No element picked yet
              </div>
              <div className="flex flex-wrap gap-1">
                <span
                  data-d="badge"
                  className="rounded-md border border-line-strong px-1.5 py-0.5 font-mono text-[9px] text-ink-soft opacity-0"
                >
                  {`<${PICKED_TAG}>`}
                </span>
                {PICKED_CLASSES.slice(0, 3).map((name) => (
                  <span
                    key={name}
                    data-d="badge"
                    className="rounded-md border border-line-strong px-1.5 py-0.5 font-mono text-[9px] text-ink-soft opacity-0"
                  >
                    .{name}
                  </span>
                ))}
              </div>
              <div className="grid grid-cols-4 gap-1">
                {['W', 'H', 'X', 'Y'].map((name, index) => (
                  <div
                    key={name}
                    data-d="stat"
                    className="rounded-md border border-line py-0.5 text-center opacity-0"
                  >
                    <p
                      data-d={`stat-${index}`}
                      className="text-[11px] font-semibold tabular-nums text-ink"
                    >
                      0
                    </p>
                    <p className="text-[8.5px] text-muted">{name}</p>
                  </div>
                ))}
              </div>
              <Section title="Attributes">
                {ATTRIBUTES.map(([name, value]) => (
                  <p key={name} data-d="row" className="truncate">
                    <span className="text-[var(--accent)]">{name}</span>=
                    <span className="text-muted">&quot;{value}&quot;</span>
                  </p>
                ))}
              </Section>
              <Section title="Computed styles" d="copy-styles">
                {STYLES.map(([name, value]) => (
                  <p key={name} data-d="row" className="flex items-center gap-1 truncate">
                    <span className="text-[var(--accent)]">{name}:</span>
                    <span className="text-muted">{value}</span>
                    {name === 'background-color' ? (
                      <span className="size-2 rounded-sm bg-[#7c3aed]" />
                    ) : null}
                  </p>
                ))}
              </Section>
            </div>
          </div>
        }
      >
        <MockPage variant="landing" />
        <span
          data-d="picking"
          className="absolute right-2 top-11 rounded-full bg-[#312e81] px-2 py-0.5 font-mono text-[9px] text-white opacity-0"
        >
          Click an element · Esc to cancel
        </span>
      </BrowserChrome>
      <div
        data-d="ov"
        className="pointer-events-none absolute left-0 top-0 z-30 size-2 rounded-[2px] border-2 border-[#6366f1] bg-[rgba(99,102,241,0.12)] opacity-0"
      >
        <span
          data-d="ov-label"
          className="absolute -top-[18px] left-[-2px] whitespace-nowrap rounded-[3px] bg-[#312e81] px-1.5 py-px font-mono text-[9px] text-white"
        />
      </div>
    </DemoStage>
  )
}
